1	# Data Model: Authentication and User Onboarding
2	
3	**Phase**: 1 | **Branch**: `001-auth-onboarding`
4	
5	## Domain Entities
6	
7	### User (Aggregate Root)
8	
9	Represents a person who can sign in. Administrators and standard users are distinguished by
10	`SystemRole`. The Google subject identifier (`google_sub`) is the stable identity — not the
11	email — so that a Google email change does not break sign-in.
12	
13	```csharp
14	public sealed class User
15	{
16	    public Guid Id { get; }
17	    public string Email { get; }
18	    public string DisplayName { get; }
19	    public SystemRole SystemRole { get; }
20	    public string? GoogleSub { get; private set; }      // null until first sign-in
21	    public DateTimeOffset RegisteredAt { get; }
22	    public DateTimeOffset? LastSignInAt { get; private set; }
23	
24	    public User(Guid id, string email, string displayName, SystemRole systemRole,
25	                string? googleSub, DateTimeOffset registeredAt, DateTimeOffset? lastSignInAt)
26	    {
27	        Verify.That(id).IsNotDefault();
28	        Verify.That(email).IsNotNull().IsNotEmpty();
29	        Verify.That(displayName).IsNotNull().IsNotEmpty();
30	        RegisteredAt = registeredAt;
31	        // ... assign all fields
32	    }
33	
34	    public void LinkGoogleIdentity(string googleSub)
35	    {
36	        Verify.That(googleSub).IsNotNull().IsNotEmpty();
37	        GoogleSub = googleSub;
38	    }
39	
40	    public void RecordSignIn(DateTimeOffset signedInAt) => LastSignInAt = signedInAt;
41	}
42	```
43	
44	### Invitation (Aggregate Root)
45	
46	Represents a pending or consumed offer for a person to become a registered user. The raw
47	redemption token is never stored — only its SHA-256 hash.
48	
49	```csharp
50	public sealed class Invitation
51	{
52	    public Guid Id { get; }
53	    public string Email { get; }                        // email the invitation was issued to
54	    public Guid IssuedByUserId { get; }
55	    public string TokenHash { get; }                    // SHA-256 hex of raw token
56	    public DateTimeOffset IssuedAt { get; }
57	    public DateTimeOffset ExpiresAt { get; }
58	    public DateTimeOffset? ConsumedAt { get; private set; }
59	    public Guid? ConsumedByUserId { get; private set; }
60	
61	    public bool IsExpired => DateTimeOffset.UtcNow > ExpiresAt;
62	    public bool IsConsumed => ConsumedAt.HasValue;
63	    public bool IsRedeemable => !IsExpired && !IsConsumed;
64	
65	    public bool EmailMatches(string googleEmail)
66	    {
67	        Verify.That(googleEmail).IsNotNull().IsNotEmpty();
68	        return string.Equals(Email, googleEmail, StringComparison.OrdinalIgnoreCase);
69	    }
70	
71	    public void Consume(Guid userId, DateTimeOffset consumedAt)
72	    {
73	        Verify.That(userId).IsNotDefault();
74	        ConsumedAt = consumedAt;
75	        ConsumedByUserId = userId;
76	    }
77	}
78	```
79	
80	### InvitationToken (Value Object)
81	
82	Encapsulates token generation and hashing. Ensures the raw token never leaks into storage.
83	
84	```csharp
85	public sealed record InvitationToken
86	{
87	    public string Raw { get; }        // returned to admin, never stored
88	    public string Hash { get; }       // SHA-256 hex — stored in DB
89	
90	    private InvitationToken(string raw, string hash) { Raw = raw; Hash = hash; }
91	
92	    public static InvitationToken Generate()
93	    {
94	        var bytes = RandomNumberGenerator.GetBytes(32);
95	        var raw = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
96	        var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(raw))).ToLower();
97	        return new InvitationToken(raw, hash);
98	    }
99	
100	    public static string HashRaw(string rawToken)
101	    {
102	        Verify.That(rawToken).IsNotNull().IsNotEmpty();
103	        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(rawToken))).ToLower();
104	    }
105	}
106	```
107	
108	### AuthEvent (Audit Record)
109	
110	Immutable record of a notable auth lifecycle moment. No PII — only GUIDs and outcome codes.
111	
112	```csharp
113	public sealed record AuthEvent(
114	    Guid Id,
115	    DateTimeOffset OccurredAt,
116	    AuthEventType EventType,
117	    Guid? UserId,           // nullable: e.g., acceptance refused for unknown token
118	    string Outcome          // "Success", "NotRegistered", "TokenExpired", etc.
119	);
120	```
121	
122	### Enumerations
123	
124	```csharp
125	public enum SystemRole  { Admin, Standard }
126	public enum AuthEventType { SignIn, SignOut, InvitationIssued, InvitationAccepted, AcceptanceRefused }
127	```
128	
129	---
130	
131	## Database Schema
132	
133	### SQLite Migration: `001_initial_schema.sql`
134	
135	```sql
136	CREATE TABLE IF NOT EXISTS users (
137	    id              TEXT NOT NULL PRIMARY KEY,
138	    email           TEXT NOT NULL,
139	    display_name    TEXT NOT NULL,
140	    system_role     TEXT NOT NULL DEFAULT 'Standard',
141	    google_sub      TEXT,
142	    registered_at   TEXT NOT NULL,
143	    last_sign_in_at TEXT,
144	    CONSTRAINT uq_users_email      UNIQUE (email),
145	    CONSTRAINT uq_users_google_sub UNIQUE (google_sub)
146	);
147	
148	CREATE TABLE IF NOT EXISTS invitations (
149	    id                   TEXT NOT NULL PRIMARY KEY,
150	    email                TEXT NOT NULL,
151	    issued_by_user_id    TEXT NOT NULL REFERENCES users(id),
152	    token_hash           TEXT NOT NULL,
153	    issued_at            TEXT NOT NULL,
154	    expires_at           TEXT NOT NULL,
155	    consumed_at          TEXT,
156	    consumed_by_user_id  TEXT REFERENCES users(id),
157	    CONSTRAINT uq_invitations_token_hash UNIQUE (token_hash)
158	);
159	
160	CREATE INDEX IF NOT EXISTS ix_invitations_email      ON invitations(email);
161	CREATE INDEX IF NOT EXISTS ix_invitations_token_hash ON invitations(token_hash);
162	
163	CREATE TABLE IF NOT EXISTS auth_events (
164	    id           TEXT NOT NULL PRIMARY KEY,
165	    occurred_at  TEXT NOT NULL,
166	    event_type   TEXT NOT NULL,
167	    user_id      TEXT REFERENCES users(id),
168	    outcome      TEXT NOT NULL
169	);
170	
171	CREATE INDEX IF NOT EXISTS ix_auth_events_occurred_at ON auth_events(occurred_at);
172	```
173	
174	### SQLite Migration: `002_seed_admin.sql`
175	
176	```sql
177	INSERT OR IGNORE INTO users (id, email, display_name, system_role, google_sub, registered_at)
178	VALUES (
179	    '$AdminUserId$',
180	    '$AdminEmail$',
181	    'Administrator',
182	    'Admin',
183	    NULL,
184	    '$SeedTimestamp$'
185	);
186	```
187	
188	Variables injected by DbUp at startup from `IOptions<SeedOptions>` and `IOptions<SeedMetaOptions>`.
189	`google_sub` is NULL — populated on first Google sign-in.
190	
191	### PostgreSQL Variants (`migrations/postgres/`)
192	
193	Identical DDL except:
194	- `TEXT` primary keys remain `TEXT` (Postgres supports this; GUID stored as text for portability)
195	- `CREATE INDEX IF NOT EXISTS` syntax is identical in Postgres 9.5+
196	- `INSERT OR IGNORE` → `INSERT INTO ... ON CONFLICT DO NOTHING`
197	
198	---
199	
200	## Repository Interfaces
201	
202	```csharp
203	// Kanban.DataAccess/Interfaces/IUserRepository.cs
204	public interface IUserRepository
205	{
206	    Task<User?> FindByGoogleSubAsync(string googleSub, IDbTransaction? tx = null);
207	    Task<User?> FindByEmailAsync(string email, IDbTransaction? tx = null);
208	    Task<User?> FindByIdAsync(Guid id, IDbTransaction? tx = null);
209	    Task InsertAsync(User user, IDbTransaction tx);
210	    Task LinkGoogleSubAsync(Guid userId, string googleSub, IDbTransaction tx);
211	    Task UpdateLastSignInAsync(Guid userId, DateTimeOffset signedInAt, IDbTransaction tx);
212	}
213	
214	// Kanban.DataAccess/Interfaces/IInvitationRepository.cs
215	public interface IInvitationRepository
216	{
217	    Task<Invitation?> FindByTokenHashAsync(string tokenHash, IDbTransaction? tx = null);
218	    Task<Invitation?> FindActiveByEmailAsync(string email, IDbTransaction? tx = null);
219	    Task InsertAsync(Invitation invitation, IDbTransaction tx);
220	    // Consume is handled via a targeted UPDATE (see concurrent acceptance pattern)
221	    Task<bool> TryConsumeAsync(string tokenHash, Guid userId, DateTimeOffset consumedAt,
222	                               IDbTransaction tx);
223	}
224	
225	// Kanban.DataAccess/Interfaces/IAuthEventRepository.cs
226	public interface IAuthEventRepository
227	{
228	    Task RecordAsync(AuthEvent authEvent, IDbTransaction tx);
229	}
230	```
231	
232	`TryConsumeAsync` executes:
233	```sql
234	UPDATE invitations
235	SET consumed_at = @consumedAt, consumed_by_user_id = @userId
236	WHERE token_hash = @tokenHash
237	  AND consumed_at IS NULL
238	  AND expires_at > @now
239	```
240	Returns `true` if `rowsAffected == 1`, `false` otherwise.
241

