using System.Numerics;
using System.Runtime.CompilerServices;

namespace Kanban.Domain;

public static class Verify
{
    public static ParameterVerifier<T> That<T>(
        T value,
        [CallerArgumentExpression(nameof(value))] string paramName = "")
        => new(value, paramName);
}

public sealed class ParameterVerifier<T>(T value, string paramName)
{
    public ParameterVerifier<T> IsNotNull()
    {
        if (value is null)
            throw new ArgumentNullException(paramName);
        return this;
    }

    public ParameterVerifier<T> IsNotDefault()
    {
        if (EqualityComparer<T>.Default.Equals(value, default))
            throw new ArgumentException($"Value must not be default.", paramName);
        return this;
    }
}

public static class StringVerifierExtensions
{
    public static ParameterVerifier<string> IsNotEmpty(this ParameterVerifier<string> verifier)
    {
        verifier.IsNotNull();
        var field = typeof(ParameterVerifier<string>).GetField("value",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        var val = (string?)field!.GetValue(verifier);
        var name = typeof(ParameterVerifier<string>).GetField("paramName",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        var paramName = (string?)name!.GetValue(verifier);

        if (string.IsNullOrEmpty(val))
            throw new ArgumentException("Value must not be empty.", paramName);
        return verifier;
    }

    public static ParameterVerifier<string> HasMaxLength(this ParameterVerifier<string> verifier, int max)
    {
        var field = typeof(ParameterVerifier<string>).GetField("value",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        var val = (string?)field!.GetValue(verifier);
        var name = typeof(ParameterVerifier<string>).GetField("paramName",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        var paramName = (string?)name!.GetValue(verifier);

        if (val is not null && val.Length > max)
            throw new ArgumentException($"Value must not exceed {max} characters.", paramName);
        return verifier;
    }
}

