        ex.Should().BeAssignableTo<KanbanException>();
    }

    [Fact]
    public void InfrastructureException_InheritsFromKanbanException()
    {
        var ex = new DataAccessException("x", "x");
        ex.Should().BeAssignableTo<KanbanException>();
    }
}

