        new(
            id: Guid.NewGuid(),
            email: email ?? $"user_{Guid.NewGuid():N}@test.local",
            displayName: "Test User",
            systemRole: systemRole,
            googleSub: googleSub,
            registeredAt: registeredAt ?? DateTimeOffset.UtcNow,
            lastSignInAt: null);
}

