using Kanban.Api.Auth;
using Kanban.Business.Interfaces;
using Kanban.Contracts;
using Kanban.Domain.Entities;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication.Google;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace Kanban.Api.Endpoints;

public static class AuthEndpoints
{
    public static void Map(IEndpointRouteBuilder routes)
    {
        var auth = routes.MapGroup("/auth");

        auth.MapGet("/signin", SignIn)
            .WithName("SignIn")
            .WithSummary("Initiate Google OAuth sign-in")
            .AllowAnonymous()
            .RequireRateLimiting("anonymous");

        auth.MapGet("/me", GetMe)
            .WithName("GetCurrentUser")
            .WithSummary("Get the currently authenticated registered user")
            .Produces<CurrentUserDto>(200)
            .ProducesProblem(401)
            .ProducesProblem(403)
            .RequireAuthorization("RegisteredUser");

        auth.MapPost("/signout", SignOut)
            .WithName("SignOut")
            .WithSummary("Sign out the current user")
            .Produces(204)
            .RequireAuthorization();
    }

    private static IResult SignIn(HttpContext ctx, [FromQuery] string? returnUrl)
    {
        var redirectUri = string.IsNullOrWhiteSpace(returnUrl) ? "/" : returnUrl;
        return Results.Challenge(
            new AuthenticationProperties { RedirectUri = redirectUri },
            [GoogleDefaults.AuthenticationScheme]);
    }

    private static async Task<IResult> GetMe(
        ICurrentUserService currentUser,
        IUserRepository userRepository)
    {
        if (!currentUser.IsRegistered || !currentUser.UserId.HasValue)
            return Results.Forbid();

        var user = await userRepository.FindByIdAsync(currentUser.UserId.Value);
        if (user is null)
            return Results.Forbid();

        return Results.Ok(ToDto(user));
    }

    private static async Task<IResult> SignOut(HttpContext ctx)
    {
        await ctx.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
        return Results.NoContent();
    }

    private static CurrentUserDto ToDto(User user) => new()
    {
        Id = user.Id,
        Email = user.Email,
        DisplayName = user.DisplayName,
        SystemRole = user.SystemRole.ToString().ToLower(),
        RegisteredAt = user.RegisteredAt,
        LastSignInAt = user.LastSignInAt,
    };
}

